import { expect, test } from "bun:test";
import { TRACKED_FIXTURE_LITERALS } from "@/fixtures/tracked-fixture-literals.ts";
import {
  AUTHOR_LITERAL,
  BLOCKED_INSERT_LITERAL,
  DISTRACTOR_AUTHOR_LITERAL,
  DISTRACTOR_EXPECTED_HOUSE_LITERAL,
  DISTRACTOR_PROTAGONIST_LABEL,
  DISTRACTOR_WORK_SEARCH_LABEL,
  EXPECTED_HOUSE_LITERAL,
  PROTAGONIST_LABEL,
  UNKNOWN_WORK_SEARCH_LABEL,
  WORK_SEARCH_LABEL,
} from "@/fixtures/primary-world.ts";
import {
  HIERARCHY_CREATURE_DISCOVERY_QUERY,
  HIERARCHY_CREATURE_LABEL,
  HIERARCHY_DRAGON_LABEL,
  HIERARCHY_NEST_LABEL,
  HIERARCHY_NEST_LOCATION_LITERAL,
  HIERARCHY_TREASURE_DISCOVERY_QUERY,
  HIERARCHY_TREASURE_LABEL,
  HIERARCHY_WYVERN_LABEL,
  UNKNOWN_HIERARCHY_LABEL,
} from "@/fixtures/hierarchy-world.ts";
import {
  PAPER_YEAR_LITERAL,
  SCHOLAR_AUTHOR_LITERAL,
  SCHOLAR_PAPER_SEARCH_LABEL,
  SCHOLAR_VENUE_LITERAL,
} from "@/fixtures/scholar-world.ts";

/** FIXTURE_ANSWER_STRINGS lists every fixture string literals-subset-of-tools must track. */
const FIXTURE_ANSWER_STRINGS = [
  WORK_SEARCH_LABEL,
  PROTAGONIST_LABEL,
  AUTHOR_LITERAL,
  EXPECTED_HOUSE_LITERAL,
  DISTRACTOR_WORK_SEARCH_LABEL,
  DISTRACTOR_PROTAGONIST_LABEL,
  DISTRACTOR_AUTHOR_LITERAL,
  DISTRACTOR_EXPECTED_HOUSE_LITERAL,
  BLOCKED_INSERT_LITERAL,
  UNKNOWN_WORK_SEARCH_LABEL,
  SCHOLAR_PAPER_SEARCH_LABEL,
  SCHOLAR_AUTHOR_LITERAL,
  SCHOLAR_VENUE_LITERAL,
  PAPER_YEAR_LITERAL,
  HIERARCHY_CREATURE_LABEL,
  HIERARCHY_CREATURE_DISCOVERY_QUERY,
  HIERARCHY_DRAGON_LABEL,
  HIERARCHY_WYVERN_LABEL,
  HIERARCHY_NEST_LABEL,
  HIERARCHY_NEST_LOCATION_LITERAL,
  HIERARCHY_TREASURE_LABEL,
  HIERARCHY_TREASURE_DISCOVERY_QUERY,
  UNKNOWN_HIERARCHY_LABEL,
] as const;

test("TRACKED_FIXTURE_LITERALS includes every fixture answer string", () => {
  const trackedSet = new Set<string>(TRACKED_FIXTURE_LITERALS);
  const missingStrings = FIXTURE_ANSWER_STRINGS.filter(
    (fixtureString) => !trackedSet.has(fixtureString),
  );
  expect(missingStrings).toEqual([]);
});
